import assert from 'node:assert/strict'
import { registerHooks } from 'node:module'
const edits = {
  'copy-only': ['const originalOwners = new Map(graph.declarationSymbols);', 'const originalOwners = graph.declarationSymbols;'],
  'cache-only': ['const { byName, originallyExported, declarationSymbols: originalOwners } = graph;', 'const { byName, originallyExported } = graph; const originalOwners = new Map(graph.declarationSymbols);'],
}
registerHooks({ load(url, context, nextLoad) {
  const loaded = nextLoad(url, context)
  if (!url.endsWith('/router-utils/dist/esm/compiler-helpers.js')) { return loaded }
  const source = typeof loaded.source === 'string' ? loaded.source : Buffer.from(loaded.source).toString()
  const [before, after] = edits[process.env.CLEANUP_ATTRIBUTION]
  assert.ok(source.includes(before), 'Expected attribution hunk missing')
  return { ...loaded, source: source.replace(before, after) }
}})
